package io.ecosync.restgateway;
import io.ecosync.restcontract.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

/** Actual local sockets, injected DNS, no public internet. Parser-only tests are separate. */
class SocketTransportTest {
 @Test void jsonEscapedCredentialReflectionIsBlockedBeforeResultRelease()throws Exception{var address=address();try(var server=new ServerSocket(0,4,address);var pool=Executors.newVirtualThreadPerTaskExecutor();var policy=new DestinationPolicy("http://fixture:"+server.getLocalPort()+"|dev",address.getHostAddress()+"/32",true,h->new InetAddress[]{address});var operations=new Operations();var op=operations.begin(UUID.randomUUID(),"reflection")){
  String secret="reflection-\"quoted\\secret-123456";var cfg=new HashMap<>(config(server.getLocalPort()));cfg.put("secret",secret);cfg.put("operation",Map.of("path","/lookup","parameters",List.of(),"responses",Map.of("200",RestSchema.normalize(Map.of("type","object"),true))));byte[] body=RestJson.MAPPER.writeValueAsBytes(Map.of("nested",Map.of("value",secret)));assertThat(new String(body,StandardCharsets.UTF_8)).doesNotContain(secret);var source=pool.submit(()->{try(var socket=server.accept()){socket.setSoTimeout(4000);var reader=new BufferedReader(new InputStreamReader(socket.getInputStream()));while(!reader.readLine().isEmpty()){}socket.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+body.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().write(body);return true;}});assertThatThrownBy(()->new PinnedHttp(policy).get(cfg,Map.of(),op,()->{})).isInstanceOf(RestFailure.class).extracting(e->((RestFailure)e).code).isEqualTo("REST_INVALID_RESPONSE");source.get(5,TimeUnit.SECONDS);
 }}
 @Test void ambientSocksProxyCannotReplaceThePinnedSourceConnection()throws Exception{var address=address();String priorHost=System.getProperty("socksProxyHost"),priorPort=System.getProperty("socksProxyPort");try(var target=new ServerSocket(0,4,address);var proxy=new ServerSocket(0,4,address);var pool=Executors.newVirtualThreadPerTaskExecutor();var policy=new DestinationPolicy("http://fixture:"+target.getLocalPort()+"|dev",address.getHostAddress()+"/32",true,h->new InetAddress[]{address});var operations=new Operations();var op=operations.begin(UUID.randomUUID(),"no-proxy")){
  System.setProperty("socksProxyHost",address.getHostAddress());System.setProperty("socksProxyPort",Integer.toString(proxy.getLocalPort()));var source=pool.submit(()->{try(var socket=target.accept()){socket.setSoTimeout(4000);var reader=new BufferedReader(new InputStreamReader(socket.getInputStream()));while(!reader.readLine().isEmpty()){}socket.getOutputStream().write("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 11\r\n\r\n{\"ok\":true}".getBytes(StandardCharsets.US_ASCII));return true;}});assertThat(new PinnedHttp(policy).get(config(target.getLocalPort()),Map.of(),op,()->{}).get("status")).isEqualTo(200);source.get(5,TimeUnit.SECONDS);proxy.setSoTimeout(200);assertThatThrownBy(proxy::accept).isInstanceOf(SocketTimeoutException.class);
 }finally{if(priorHost==null)System.clearProperty("socksProxyHost");else System.setProperty("socksProxyHost",priorHost);if(priorPort==null)System.clearProperty("socksProxyPort");else System.setProperty("socksProxyPort",priorPort);}}
 InetAddress address()throws Exception{return Collections.list(NetworkInterface.getNetworkInterfaces()).stream().flatMap(n->Collections.list(n.getInetAddresses()).stream()).filter(a->a instanceof Inet4Address&&!a.isLoopbackAddress()&&a.isSiteLocalAddress()).findFirst().orElseThrow();}
 Map<String,Object> config(int port){var schema=RestSchema.normalize(Map.of("type","object","properties",Map.of("ok",Map.of("type","boolean")),"required",List.of("ok"),"additionalProperties",false),true);return Map.of("baseUrl","http://fixture:"+port,"authType","HEADER_API_KEY","authHeader","X-Test-Key","secret","socket-test-secret-123456789","operation",Map.of("path","/lookup","parameters",List.of(Map.of("name","name","in","query","required",false,"schema",RestSchema.normalize(Map.of("type","string"),true))),"responses",Map.of("200",schema)));}
 @Test void validatedAddressIsUsedForActualSocketAndHostAndAuthRemainOriginal()throws Exception{var address=address();try(var server=new ServerSocket(0,4,address);var pool=Executors.newVirtualThreadPerTaskExecutor();var policy=new DestinationPolicy("http://fixture:"+server.getLocalPort()+"|dev",address.getHostAddress()+"/32",true,h->new InetAddress[]{address});var operations=new Operations();var op=operations.begin(UUID.randomUUID(),"fixture")){
  var source=pool.submit(()->{try(var socket=server.accept()){socket.setSoTimeout(4000);var reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));var lines=new ArrayList<String>();for(String line;!(line=reader.readLine()).isEmpty();)lines.add(line);socket.getOutputStream().write("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 11\r\n\r\n{\"ok\":true}".getBytes(StandardCharsets.US_ASCII));return lines;}});var authority=new AtomicInteger();var result=new PinnedHttp(policy).get(config(server.getLocalPort()),Map.of("name","River & Pine"),op,authority::incrementAndGet);assertThat(result.get("status")).isEqualTo(200);assertThat(source.get(5,TimeUnit.SECONDS)).contains("GET /lookup?name=River%20%26%20Pine HTTP/1.1","Host: fixture:"+server.getLocalPort(),"X-Test-Key: socket-test-secret-123456789");assertThat(authority.get()).isGreaterThanOrEqualTo(3);
 }}
 @Test void rebindBetweenAdmissionAndConnectionCausesZeroOutboundSockets()throws Exception{var address=address();try(var server=new ServerSocket(0,4,address);var policy=new DestinationPolicy("http://fixture:"+server.getLocalPort()+"|dev",address.getHostAddress()+"/32",true,new DestinationPolicy.Resolver(){int calls;public InetAddress[] lookup(String h)throws Exception{return new InetAddress[]{++calls==1?address:InetAddress.getByName("169.254.169.254")};}});var operations=new Operations();var op=operations.begin(UUID.randomUUID(),"fixture")){assertThatThrownBy(()->new PinnedHttp(policy).get(config(server.getLocalPort()),Map.of(),op,()->{})).isInstanceOf(RestFailure.class);server.setSoTimeout(200);assertThatThrownBy(server::accept).isInstanceOf(SocketTimeoutException.class);}}
 @Test void rejectedRedirectDoesNotConnectToLocationOrLeakCredential()throws Exception{var address=address();try(var server=new ServerSocket(0,4,address);var trap=new ServerSocket(0,4,address);var pool=Executors.newVirtualThreadPerTaskExecutor();var policy=new DestinationPolicy("http://fixture:"+server.getLocalPort()+"|dev",address.getHostAddress()+"/32",true,h->new InetAddress[]{address});var operations=new Operations();var op=operations.begin(UUID.randomUUID(),"fixture")){var source=pool.submit(()->{try(var socket=server.accept()){var reader=new BufferedReader(new InputStreamReader(socket.getInputStream()));while(!reader.readLine().isEmpty()){}socket.getOutputStream().write(("HTTP/1.1 302 Found\r\nLocation: http://"+address.getHostAddress()+":"+trap.getLocalPort()+"/steal\r\nContent-Length: 0\r\n\r\n").getBytes(StandardCharsets.US_ASCII));return true;}});assertThatThrownBy(()->new PinnedHttp(policy).get(config(server.getLocalPort()),Map.of(),op,()->{})).isInstanceOf(RestFailure.class).extracting(e->((RestFailure)e).code).isEqualTo("REST_REDIRECT_DENIED");source.get(5,TimeUnit.SECONDS);trap.setSoTimeout(200);assertThatThrownBy(trap::accept).isInstanceOf(SocketTimeoutException.class);}}
 @Test void boundedDnsLookupCannotOccupyCallerIndefinitely(){try(var policy=new DestinationPolicy("http://fixture:8095|dev","",true,h->{Thread.sleep(5000);return new InetAddress[0];})){long start=System.nanoTime();assertThatThrownBy(()->policy.resolve(policy.target("http://fixture:8095"))).isInstanceOf(RestFailure.class);assertThat(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)).isLessThan(3000);}}
}
